// Grammar
// =============================================================================

/// Node spans and rule ids are recorded (`@schema` or `--spans`).
pub const nodeStore = false;
/// Element extents are kept for side-band labels and nested nodes.
const elemEnds = false;
/// Lists keep trailing nils: positions are fixed by the schema.
const keepTrailingNils = false;
const hasTrivia = false;
const hasRepair = false;
/// `@as` groups the promotable token may become (see `promote`).
const asGroups = 4;
const numSymbols = 259;
const endSymbol: u16 = 1;
const errorSymbol: u16 = 2;

fn tokenToSymbol(token: Token) u16 {
    return switch (token.cat) {
        .@"eof" => 1,
        .@"ident" => needsPromotion,
        .@"integer" => 110,
        .@"zdigits" => 111,
        .@"comment" => 113,
        .@"newline" => 115,
        .@"spaces" => 116,
        .@"indent" => 123,
        .@"string" => 179,
        .@"exclaim_ws" => 184,
        .@"hash_ws" => 185,
        .@"patend" => 187,
        .@"quesat" => 190,
        .@"colon_ws" => 198,
        .@"real" => 241,
        .@"notques" => 214,
        .@"eqeq" => 219,
        .@"noteq" => 220,
        .@"notlt" => 223,
        .@"notgt" => 224,
        .@"notlbracket" => 229,
        .@"notrbracket" => 230,
        .@"followseq" => 231,
        .@"sortsafter" => 232,
        .@"sortsaftereq" => 233,
        .@"notampersand" => 235,
        .@"notexclaim" => 236,
        .@"lparen" => 118,
        .@"comma" => 119,
        .@"rparen" => 122,
        .@"dot" => 124,
        .@"colon" => 128,
        .@"at" => 131,
        .@"eq" => 132,
        .@"dollar" => 134,
        .@"plus" => 155,
        .@"caret" => 156,
        .@"pipe" => 165,
        .@"slash" => 176,
        .@"star" => 177,
        .@"hash" => 178,
        .@"exclaim" => 183,
        .@"question" => 186,
        .@"minus" => 195,
        .@"not" => 215,
        .@"underscore" => 216,
        .@"backslash" => 217,
        .@"lt" => 221,
        .@"gt" => 222,
        .@"lbracket" => 227,
        .@"rbracket" => 228,
        .@"ampersand" => 234,
        .@"starstar" => 218,
        .@"lteq" => 225,
        .@"gteq" => 226,
        else => 2, // error
    };
}

fn promote(self: *BaseParser, token: Token) u16 {
    // The ordinal of a match made in an earlier state (before a
    // reduction) is not this match's.
    self.lastMatchedId = 0;
    const text = self.source[token.pos..][0..token.len];
    if (text.len == 0) return promotableSymbol;
    if (self.tryPromote(0, text, lang.fnAs, &fnToSymbol, fnFallbackSymbol, false)) |sym| return sym;
    if (self.tryPromote(1, text, lang.isvAs, &isvToSymbol, isvFallbackSymbol, false)) |sym| return sym;
    if (self.tryPromote(2, text, lang.ssvnAs, &ssvnToSymbol, ssvnFallbackSymbol, false)) |sym| return sym;
    if (getAction(self.stateStack.last().?, promotableSymbol) != 0) return promotableSymbol;
    if (self.tryPromote(3, text, lang.cmdAs, &cmdToSymbol, cmdFallbackSymbol, true)) |sym| return sym;
    return promotableSymbol;
}

